<template><AdminCardList :data="items" row-key="id" title="name" :fields="fields" :actions="actions" @action="handleAction"/></template>
<script setup lang="ts">import{computed}from'vue';import{Delete,Edit}from'@element-plus/icons-vue';import AdminCardList,{type AdminCardActionConfig,type AdminCardFieldConfig}from'@/components/admin/AdminCardList.vue';import type{RoleItem}from'../types';const props=defineProps<{items:RoleItem[];canEdit:boolean;canDelete:boolean}>();const emit=defineEmits<{(e:'edit',row:RoleItem):void;(e:'delete',row:RoleItem):void}>();const fields:AdminCardFieldConfig[]=[{label:'角色描述',value:(row)=>(row as RoleItem).description||'—'},{label:'管理員',value:(row)=>`${(row as RoleItem).admin_count} 人`},{label:'創建時間',prop:'created_at'}];const actions=computed<AdminCardActionConfig[]>(()=>[...(props.canEdit?[{key:'edit',label:'編輯',icon:Edit,type:'primary' as const,plain:true}]:[]),...(props.canDelete?[{key:'delete',label:'刪除',icon:Delete,type:'danger' as const,plain:true,visible:(row:object)=>(row as RoleItem).admin_count===0}]:[])]);function handleAction(action:string,_key:string,row?:object){if(action==='edit')emit('edit',row as RoleItem);if(action==='delete')emit('delete',row as RoleItem)}</script>
